'use strict';
const ChallengeFactory=(()=>{
 const types=['different','count','memory','arithmetic','pattern','logic','code'];
 const variants=['bow','nails','button','stripe','earring'];
 const variantNames={bow:'un moño pequeño',nails:'adornos rosas en las botas',button:'un botón rosa',stripe:'una rayita en la manga',earring:'un arete rosa'};
 function rng(seed){let s=seed>>>0;return ()=>{s+=0x6D2B79F5;let t=s;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return ((t^t>>>14)>>>0)/4294967296}}
 function generator(seed){const random=rng(seed),int=(a,b)=>a+Math.floor(random()*(b-a+1));const shuffle=a=>{a=[...a];for(let i=a.length-1;i>0;i--){const j=int(0,i);[a[i],a[j]]=[a[j],a[i]]}return a};
 function choices(answer){const vals=new Set([String(answer)]);while(vals.size<4)vals.add(String(Number(answer)+int(-9,12)));return shuffle([...vals])}
 function make(type,index){const tier=Math.floor(index/10);let l={type};
 if(type==='different'){const total=12+tier*2,variant=variants[int(0,4)];return {...l,total,variant,answer:int(0,total-1),faces:Array.from({length:total},()=>random()<.5?'R':'L'),title:'Detectives de los detalles',instructions:'Entre todas estas patas, una tiene un detalle diferente. Las flechas no cuentan: busca el detalle en su ropa o accesorios.',hint:'Revisa '+({bow:'el cabello',nails:'las botas',button:'el botón del traje',stripe:'las mangas',earring:'el arete junto al cabello'}[variant])+', una fila a la vez.'}}
 if(type==='count'){const total=int(18+tier*2,24+tier*3),mode=int(0,3),faces=Array.from({length:total},()=>random()<.5?'R':'L'),decorations=Array.from({length:total},()=>random()<.45?'bow':'');const matches=faces.map((f,i)=>mode===0?f==='R'&&decorations[i]==='bow':mode===1?f==='L'&&decorations[i]!=='bow':mode===2?decorations[i]==='bow':f==='R');const count=matches.filter(Boolean).length;return {...l,total,faces,decorations,count,answer:String(count),choices:choices(count),mode,title:'Cuenta con lupa',instructions:['Cuenta solo las que tienen flecha → Y llevan moño.','Cuenta solo las que tienen flecha ← Y NO llevan moño.','¿Cuántas patas llevan moño, sin importar su flecha?','¿Cuántas patas tienen flecha →? Las otras no cuentan.'][mode],hint:'Primero descarta las que no cumplen la regla. Luego cuenta por filas sin saltarte ninguna.'}}
 if(type==='memory'){const length=6+Math.min(tier,3),sequence=Array.from({length},()=>random()<.5?'L':'R'),reverse=tier>=2&&random()<.6;return {...l,sequence,reverse,expected:reverse?[...sequence].reverse():sequence,seconds:Math.max(5,8-tier),title:reverse?'El baile al revés':'El baile secreto',instructions:reverse?'Memoriza el baile. Después repítelo AL REVÉS: empieza por la última pata.':'Memoriza las direcciones de izquierda a derecha y repítelas cuando se oculten.',hint:reverse?'Empieza por la última dirección que viste y retrocede una por una. Puedes volver a mirar.':'Separa el baile en grupos de dos o tres direcciones. Puedes volver a mirar.'}}
 if(type==='arithmetic'){const mode=int(0,2),a=int(4,9+tier*2),b=int(3,8+tier),c=int(2,9);let answer,question,hint;if(mode===0){answer=a*b-c;question=`${a} patas llevan ${b} conchas cada una. Regalan ${c} conchas en total. ¿Cuántas les quedan entre todas?`;hint='Primero multiplica patas por conchas. Después resta las que regalaron.'}else if(mode===1){const total=a*4;answer=a*3;question=`Había ${total} helados. Las patas se comieron una cuarta parte. ¿Cuántos helados quedan?`;hint='Divide el total entre cuatro para saber cuántos comieron. Después resta esa cantidad.'}else{answer=a*b+c;question=`Compras ${b} jugos de ${a} monedas y una galleta de ${c} monedas. ¿Cuánto pagas en total?`;hint='Calcula primero el precio de todos los jugos. Después suma la galleta.'}return {...l,mode,a,b,c,title:'La tienda de la playa',question,answer:String(answer),choices:choices(answer),hint}}
 if(type==='pattern'){const start=int(2,15),a=int(2,6+tier),b=int(2,5+tier),mode=int(0,2);let nums=[start];for(let n=0;n<6;n++)nums.push(mode===0?nums[n]+a+n:mode===1?nums[n]+(n%2?b:a):nums[n]*2+a);const answer=nums.pop();return {...l,mode,a,b,start,title:'El número escondido',question:'¿Qué número sigue en esta serie?',display:nums.join(' · ')+' · ?',answer:String(answer),choices:choices(answer),hint:mode===0?'Las cantidades que se suman van aumentando de una en una.':mode===1?'Hay dos sumas que se turnan. Compara el primer salto con el tercero.':'Duplica un número y después suma siempre la misma cantidad.'}}
 if(type==='logic'){const order=shuffle(['Luna','Vera','Mía','Alma','Nora','Iris']).slice(0,4+Math.min(tier,2)),position=int(1,order.length),clues=shuffle(order.slice(0,-1).map((name,i)=>`${name} está justo delante de ${order[i+1]}.`));return {...l,title:'La fila del helado',question:`${order.length} amigas están en una fila. ¿Quién ocupa el lugar ${position}, contando desde el principio?`,clues,order,position,answer:order[position-1],choices:shuffle(order),hint:'Busca quién no tiene a nadie delante. Esa amiga es la primera. Une las pistas para formar la fila.'}}
 const a=int(3,10+tier),b=int(2,9+tier),c=int(2,8+tier),answer=a+2*b+c;return {...l,a,b,c,title:'El código de las conchas',question:'Cada dibujo vale siempre lo mismo. ¿Cuánto vale la última operación?',clues:[`⭐ + ⭐ = ${a*2}`,`⭐ + 🐚 = ${a+b}`,`🐚 + 🌸 = ${b+c}`],display:'⭐ + 🐚 + 🐚 + 🌸 = ?',answer:String(answer),choices:choices(answer),hint:'La primera pista te da el valor de una estrella. Úsalo para descubrir la concha y luego la flor.'};
 }
 function deck(){const schedule=[];while(schedule.length<50){const batch=shuffle(types);if(batch[0]===schedule.at(-1)) [batch[0],batch[1]]=[batch[1],batch[0]];schedule.push(...batch)}const seen=new Set();return schedule.slice(0,50).map((type,i)=>{let l,key;do{l=make(type,i);key=JSON.stringify(l)}while(seen.has(key));seen.add(key);return l})}
 return {make,deck,shuffle};}
 return {generator,types,variantNames};
})();
